-- 0.8.0 · Checklists editáveis (seções e itens), checklists salvos com edição/exportação/PDF
-- e áreas equalizadas com os guias (Gerente Regional, Compras, CRM, Marketing, VM / PDV).

-- Cada aplicação guarda a estrutura do momento: editar o modelo depois não desalinha visitas já salvas.
ALTER TABLE checklist_aplicacoes ADD COLUMN IF NOT EXISTS estrutura_snap JSONB;
ALTER TABLE checklist_aplicacoes ADD COLUMN IF NOT EXISTS atualizado_em TIMESTAMPTZ;
ALTER TABLE checklist_aplicacoes ADD COLUMN IF NOT EXISTS atualizado_por TEXT;
ALTER TABLE checklist_modelos ADD COLUMN IF NOT EXISTS atualizado_em TIMESTAMPTZ;
ALTER TABLE checklist_modelos ADD COLUMN IF NOT EXISTS atualizado_por TEXT;
UPDATE checklist_aplicacoes ap SET estrutura_snap = m.estrutura
  FROM checklist_modelos m WHERE m.id = ap.modelo_id AND m.estrutura IS NOT NULL AND ap.estrutura_snap IS NULL;
CREATE OR REPLACE FUNCTION checklist_snapshot() RETURNS trigger AS $f$
BEGIN
  IF NEW.estrutura_snap IS NULL THEN SELECT estrutura INTO NEW.estrutura_snap FROM checklist_modelos WHERE id = NEW.modelo_id; END IF;
  RETURN NEW;
END $f$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS trg_checklist_snapshot ON checklist_aplicacoes;
CREATE TRIGGER trg_checklist_snapshot BEFORE INSERT ON checklist_aplicacoes FOR EACH ROW EXECUTE FUNCTION checklist_snapshot();

-- Checklists simples das áreas com guia dão lugar aos checklists do guia (aplicações antigas seguem consultáveis).
UPDATE checklist_modelos SET ativo = FALSE WHERE estrutura IS NULL AND area_id IN ('regional','compras','crm','marketing','vm');

-- Gerente Regional: mesma Visita à loja e Visita à concorrência da Supervisão (o guia é o mesmo).
INSERT INTO checklist_modelos (area_id, nome, itens, estrutura, ordem)
SELECT 'regional', m.nome, m.itens, CASE WHEN m.nome = 'Visita à loja' THEN jsonb_set(m.estrutura, '{cabecalho,3,1}', '"Gerente Regional"') ELSE m.estrutura END, CASE WHEN m.nome = 'Visita à loja' THEN 1 ELSE 2 END
  FROM checklist_modelos m
 WHERE m.area_id = 'comercial' AND m.estrutura IS NOT NULL AND m.nome IN ('Visita à loja','Visita à concorrência')
   AND NOT EXISTS (SELECT 1 FROM checklist_modelos x WHERE x.area_id = 'regional' AND x.nome = m.nome AND x.estrutura IS NOT NULL);
