INSERT INTO checklist_modelos (area_id, nome, itens, estrutura, ordem)
SELECT 'vm', $j$Concorrência — PDV & sinalização$j$, (SELECT jsonb_agg(i.v ORDER BY b.o, i.o) FROM jsonb_array_elements(x.e->'blocos') WITH ORDINALITY b(v, o), jsonb_array_elements(b.v->'itens') WITH ORDINALITY i(v, o)), x.e, 2
  FROM (SELECT $j${"escala":"comparativa","cabecalho":[["concorrente","Concorrente"],["praca","Praça / endereço"],["classificacao","Classificação (A/B/C)"],["data","Data / hora"],["responsavel","Responsável"]],"blocos":[{"nome":"Fachada & vitrine","peso":2,"area":"VM / PDV","acao":"Avaliar a prática do concorrente e propor a adaptação na Milla.","itens":["Impacto e identidade visual da fachada","Vitrine: looks, tema e promoções"]},{"nome":"Sinalização & PDV","peso":2,"area":"VM / PDV","acao":"Avaliar a prática do concorrente e propor a adaptação na Milla.","itens":["Tipos de sinalização (coleção, promoção, plus size, últimas peças)","Comunicação de preço e ofertas","Materiais de PDV no caixa (cartão, parcelamento)","QR codes / canais digitais"]},{"nome":"Exposição & layout","peso":2,"area":"VM / PDV","acao":"Avaliar a prática do concorrente e propor a adaptação na Milla.","itens":["Exposição (parede valor agregado / solo alta saída)","Densidade e cross-merchandising","Pontos quentes e mesas de oferta"]},{"nome":"Leitura estratégica","peso":2,"area":"VM / PDV","acao":"Avaliar a prática do concorrente e propor a adaptação na Milla.","itens":["Pontos fortes do concorrente","O que adaptar na Milla","Fotos de referência"]}]}$j$::jsonb AS e) x
 WHERE NOT EXISTS (SELECT 1 FROM checklist_modelos x WHERE x.area_id = 'vm' AND x.nome = $j$Concorrência — PDV & sinalização$j$ AND x.estrutura IS NOT NULL);

-- Checklists simples restantes (ex.: BigPay) passam a ter o mesmo modelo: uma seção com os itens atuais.
UPDATE checklist_modelos m SET estrutura = jsonb_build_object('escala','conformidade',
  'cabecalho', '[["loja","Loja (opcional)"],["responsavel","Responsável"],["data","Data"]]'::jsonb,
  'blocos', jsonb_build_array(jsonb_build_object('nome','Itens do checklist','peso',2,'area',(SELECT nome FROM areas WHERE id = m.area_id),
     'acao','Ajustar o ponto apontado, registrar a evidência e combinar o prazo com o responsável.','itens', m.itens)))
 WHERE m.ativo AND m.estrutura IS NULL;

-- Conteúdo das áreas equalizado com os guias (ritmo do mês, programação semanal e roteiro de conversa).
UPDATE areas SET conteudo = conteudo || $j${"rotina_loja":[["Abertura","Reunião de bom dia",["Mensagem motivacional para o time","Resultado macro da loja até o momento","Avisos da matriz (RH, DP, Compras…)","Pontos de atenção do fechamento anterior"]],["Durante o dia","Execução e acompanhamento",["Execução do checklist de loja","Acompanhamento de meta e conversão","Atividades operacionais conforme demanda","Apoio à abordagem e à venda"]],["Troca de turno / tarde","Reunião do reforço",["Mensagem motivacional para o time","Resultado macro até o momento","Avisos da matriz","Organização da loja para o fechamento"]],["Fechamento","Encerramento",["Conferência das atividades de fechamento","Caixa e indicadores do dia","Organização para o dia seguinte","Registro de pendências"]]],"conversa":[["Resultado e metas","📈",["Como está a meta do mês e o ritmo diário?","Conversão, ticket e P.A. — o que explica o número?","Quais produtos-foco estão performando?","O que precisa para virar o resultado até o fim do mês?"]],["Pessoas e quadro","👥",["Quadro completo? Há vagas em aberto?","Afastados — quem está de licença/por doença?","Férias programadas e impacto na escala?","Pedidos de desligamento ou problemas pessoais?","Advertências e ocorrências recentes?","Marketing pessoal e postura do time?"]],["Infraestrutura da loja","🏬",["Loja limpa, organizada e cheirosa?","Alguma lâmpada queimada ou iluminação fraca?","Precisa de manutenção (ar, provador, banheiro)?","Equipamentos funcionando e bem posicionados?"]],["Comercial e concorrência","🛒",["Fez o shopping de preço? O que mudou na concorrência?","Como está o abastecimento e a ruptura do salão?","Organização por preço e por departamento correta?","Vitrine e materiais da campanha aplicados?","O cartão BigPay e o bônus estão sendo oferecidos no caixa?"]]],"programacao":{"semanas":[{"n":"1ª semana","foco":"Análise e planejamento","obj":"Avaliar o resultado do mês anterior e finalizar o planejamento do mês atual, definindo prioridades e pre