},{"t":"Performance da campanha"}]},{"t":"Contextualizar cenário","c":[{"t":"Performace da Milla Ano"},{"t":"Performance da econômico da região / brasil"}]},{"t":"Resultado das prioridades","c":[{"t":"Apresentar as prioridades que from definidas no inicio do mês se foram executadas e o resultado"}]},{"t":"Resultado das expectativas alinhadas no incio do mês","c":[{"t":"Apresentar as expectativas que from definidas no inicio do mês, se foram alcançadas ."}]}]},{"t":"Plano de venda para o mês atual","c":[{"t":"Apresentação de metas e foco do mês"},{"t":"Alinhamento de expectativas e responsabilidades"},{"t":"Apresentação de ações de Marketing, VM, Compras e Bigpay de forma macro"},{"t":"Apresentar as prioridades do mês"},{"t":"Apresentar as expectativas do mês"}]},{"t":"Alinhamento de responsabilidades","c":[{"t":"Reforçar papel do gerente"},{"t":"Reforçar a importância dos checklist"},{"t":"Reforçar a importância de validar prazos, junto aos responsáveis das pendencias que impactam diretamente a operação (OS)"},{"t":"Definir pontos de controle"},{"t":"Registrar compromissos","c":[{"t":"E-mail"},{"t":"Atas"},{"t":"Sistemas de OS"}]}]}]},{"t":"Visita à loja","ref":"vloja"}]},{"d":"Sexta-feira","tasks":[{"t":"Visita à loja","ref":"vloja"}]},{"d":"Sábado","tasks":[{"t":"Visita à loja","ref":"vloja"}]},{"d":"Domingo","tasks":[]}]},{"n":"2ª semana","foco":"Acompanhamento de lojas","obj":"Avaliar execução, corrigir desvios e fortalecer a liderança local (loja).","dias":[{"d":"Segunda-feira","tasks":[{"t":"Manhã","ref":"r3"},{"t":"Tarde","ref":"r4"}]},{"d":"Terça-feira","tasks":[{"t":"Manhã","ref":"r3"},{"t":"Tarde","ref":"r4"}]},{"d":"Quarta-feira","tasks":[{"t":"Manhã","ref":"r3"},{"t":"Tarde","ref":"r4"}]},{"d":"Quinta-feira","tasks":[{"t":"Manhã","ref":"r3"},{"t":"Tarde","ref":"r4"}]},{"d":"Sexta-feira","tasks":[{"t":"Manhã","ref":"r3"},{"t":"Tarde","ref":"r4"}]},{"d":"Sábado","tasks":[{"t":"Manhã","ref":"r3"},{"t":"Tarde","ref":"r4"}]},{"d":"Domingo","tasks":[{"t":"Visita à loja","ref":"vloja"}]}]},{"n":"3ª semana","foco":"Fechamento e terceiros","obj":"Plano para melhorar o fechamento do mês e acompanhamento de demandas de terceiros que impactam a operação.","dias":[{"d":"Segunda-feira","tasks":[{"t":"Análise por loja (vendas, metas, conversão, ticket)","ref":"r1"},{"t":"Análise comparativa entre lojas e gerentes","ref":"r1"},{"t":"Análise comparativa mes e ano atual x mes e ano anterior","ref":"r1"},{"t":"Análise do abastecimento da loja","c":[{"t":"BI - Dashboard Comercial"},{"t":"Analise dos chacklist de visita da loja"}]},{"t":"Revisão consolidada das pendencias e solicitação de melhorias (OS)","ref":"r5"},{"t":"Visita à loja","ref":"vloja"}]},{"d":"Terça-feira","tasks":[{"t":"Análise por loja (vendas, metas, conversão, ticket)","ref":"r1"},{"t":"Revisão consolidada das pendencias e solicitação de melhorias (OS)","ref":"r5"},{"t":"Abastecimento","c":[{"t":"Enviar comunicação as lojas sobre demandas de abastecimento ou reposição de produto"}]},{"t":"Visita à loja","ref":"vloja"}]},{"d":"Quarta-feira","tasks":[{"t":"Reunião com marketing (campanhas, calendário)","ref":"r6"},{"t":"Reunião com compras (produtos foco, rupturas)","ref":"r6"},{"t":"Definição de foco por loja (resultado, pessoas, operação)","ref":"r6"},{"t":"Validação e ajuste de metas do mês","ref":"r6"},{"t":"Preparação de comunicados gerenciais","ref":"r6"},{"t":"Visita à loja","ref":"vloja"}]},{"d":"Quinta-feira","tasks":[{"t":"Análise por loja (vendas, metas, conversão, ticket)","ref":"r1"},{"t":"Reunião com o time da BIGPAY e Crediario Milla","c":[{"t":"Peformace da adesão ao cartão"},{"t":"Qualidade do cadastro de cliente"},{"t":"Plano de pagamento"},{"t":"Performace dos produtos financeiros"}]},{"t":"Visita à loja","ref":"vloja"}]},{"d":"Sexta-feira","tasks":[{"t":"Análise por loja (vendas, metas, conversão, ticket)","ref":"r1"},{"t":"Visita à loja","ref":"vloja"}]},{"d":"Sábado","tasks":[{"t":"Análise por loja (vendas, metas, conversão, ticket)","ref":"r1"},{"t":"Visita à loja","ref":"vloja"}]},{"d":"Domingo","tasks":[]}]},{"n":"4ª semana","foco":"Fechamento + concorrência","obj":"Plano para melhorar o fechamento do mês e acompanhamento de demandas de terceiros que impactam a operação.","dias":[{"d":"Segunda-feira","tasks":[{"t":"Análise por loja (vendas, metas, conversão, ticket)","ref":"r1"},{"t":"Visita a Concorrência","c":[{"t":"Planejar visita","c":[{"t":"Revisar consolidados checklist realizados pelas lojas e criar um cronograma de visita as lojas com maior destaque"}]},{"t":"Observar práticas","c":[{"t":"Registra sugestão e operação"}]},{"t":"Comparar com Milla","c":[{"t":"Registrar evidencias para sem apresentadas ao responsavel"}]},{"t":"Identificar oportunidades","c":[{"t":"Registrar por meio de fotos ou descrição para se apresenta imediatamente ao responsavel e na reunião de alinhamento semanal"}]}]},{"t":"Visita à loja","ref":"vloja"}]},{"d":"Terça-feira","tasks":[{"t":"Análise por loja (vendas, metas, conversão, ticket)","ref":"r1"},{"t":"Apresentação do fechamento do mês","c":[{"t":"Iniciar o desenvolvimento da apresentação"},{"t":"Consolidação das informações"}]},{"t":"Visita à loja","ref":"vloja"}]},{"d":"Quarta-feira","tasks":[{"t":"Visita à loja","ref":"vloja"}]},{"d":"Quinta-feira","tasks":[{"t":"Visita à loja","ref":"vloja"}]},{"d":"Sexta-feira","tasks":[{"t":"Visita à loja","ref":"vloja"}]},{"d":"Sábado","tasks":[{"t":"Visita à loja","ref":"vloja"}]},{"d":"Domingo","tasks":[{"t":"Visita à loja","ref":"vloja"}]}]}],"blocos":{"vloja":[{"t":"Reunião de bom dia (Abertura da loja)","c":[{"t":"Acompanhamento da reunião de abertura da loja, onde o gerente passas as seguintes mensagens","c":[{"t":"Mesagem motivacional para o time"},{"t":"Apresentação do resultado macro da peformace da loja até o dia e horario da reunião"},{"t":"Avisos da matriz (RH, DP, Compras ....)"},{"t":"Pontos de atenção as atividade de fechamento de loja não realizado"}]}]},{"t":"Reunão de troca de turno ou a tarde","c":[{"t":"Acompanhamento da reunião de troca de turno ou chegada do time de reforço da loja, onde o gerente passas as seguintes mensagens","c":[{"t":"Mesagem motivacional para o time"},{"t":"Apresentação do resultado macro da peformace da loja até o dia e horario da reunião"},{"t":"Avisos da matriz (RH, DP, Compras ....)"},{"t":"Organização da loja para o fechamento"}]}]},{"t":"Execução de checklist"},{"t":"Execução de atividade operacionais conforme demanda"}],"vtec":[{"t":"Análise de indicadores com gerente","c":[{"t":"Venda","c":[{"t":"BI - Dashboard Comercial"}]},{"t":"Meta","c":[{"t":"BI - Dashboard Comercial"}]},{"t":"Ticket","c":[{"t":"BI - Dashboard Comercial"}]},{"t":"Atendimentos","c":[{"t":"BI - Dashboard Comercial"}]},{"t":"Devoluções","c":[{"t":"BI - Dashboard Comercial"}]},{"t":"Escala de ferias","c":[{"t":"Controle interno em planilha ou sistema do RH"}]},{"t":"Escala de afastamento medico","c":[{"t":"Controle interno em planilha ou sistema do RH"}]},{"t":"Escala de feriados e finais de semanas","c":[{"t":"Controle interno em planilha ou sistema do RH"}]},{"t":"Alerta de apresentação pessoal","c":[{"t":"Controle interno em planilha ou sistema do RH"}]},{"t":"Checklist de infra estrutura da loja e concorrência","c":[{"t":"Planilha ou Google Forme"}]}]},{"t":"Avaliação da equipe e marketing pessoal","c":[{"t":"Avaliar a apresentação pessoal","c":[{"t":"Uniforme"},{"t":"Higiene pessoal (Cabelo, Barba e Maquiagem ...)"}]},{"t":"Conversa com vendedores","c":[{"t":"Campanhas","c":[{"t":"Entender se a campanha esta impactando o cliente e qual o sentimento da operação"}]},{"t":"Ruptura","c":[{"t":"Entender quais produtos estão em falta e os produtos que os cliente e a concorrencia esta trabalhando e não temos no mix da loja"}]},{"t":"Concorrência","c":[{"t":"Entender se o vendedor esta antenado e atualizado quanto os movimentos da concorrencia local, exposição preço e produto."}]}]},{"t":"Comunicados do RH / DP","c":[{"t":"Entender como o vendedor esta recebendo os comunicados da area de backoffice"}]}]},{"t":"Verificação de VM, estoque, operação e ferramentas","c":[{"t":"Verificar se os equipamentos estão organizados e sendo utilizado da forma correta. Em caso de não conformidade acionar o responsável do VM e alinhar o entendimento e depois junto orientar o gestor e equipe da loja."},{"t":"Verificar a sinalização de campanha. Em caso de não conformidade acionar o responsável do VM e Marketing e alinhar o entendimento e depois junto orientar o gestor e equipe da loja"},{"t":"Verificar organização do estoque."},{"t":"Verificar se os sistemas e depoais equipamento utilizado pela equipe de loja se estão funcionando corretamente"}]},{"t":"Discussão sobre o plano de ação com gerente","c":[{"t":"Depois de conversar com o time, alinhar visão geral da loja e definir possiveis ações para resolver questões pendentes e ações para melhor o resultado."},{"t":"Revisar junto com o gerente os checklist de pesquisa da concorrencia e de visita em loja","c":[{"t":"Checklist_Visita_Concorrentes","ptr":"conc"},{"t":"Checklist_Visita_Lojas_GrupoMilla","ptr":"loja"}]}]},{"t":"Registro de evidências e pendências (OS)","c":[{"t":"Verifica se o gestor ou lider da loja esta registrando e tenciencia de todos os pontos de necessidade da loja que depende de terceiros."}]},{"t":"Envio de comunicado : solicitando revisão de demandas e previsão de entrega do solicitado.","c":[{"t":"Apoiar o gerente da loja e enviar comunicado aos responsaives."}]}],"r1":[{"t":"BI - Dashboard Comercial"}],"r2":[{"t":"Fomulario do Google Forms"}],"r3":[{"t":"08:00–09:00 → Deslocamento para loja"},{"t":"09:00–12:00 → Visita técnica","ref":"vtec"}],"r4":[{"t":"13:00–14:00 → Deslocamento para loja"},{"t":"14:01–17:00 → Visita técnica:","ref":"vtec"}],"r5":[{"t":"Loja x compras","c":[{"t":"Reforça solicitação com o responsavel"}]},{"t":"Loja x marketing","c":[{"t":"Reforça solicitação com o responsavel"}]},{"t":"Loja x VM","c":[{"t":"Reforça solicitação com o responsavel"}]},{"t":"Loja x RH e DP","c":[{"t":"Reforça solicitação com o responsavel"}]},{"t":"Loja x TI","c":[{"t":"Reforça solicitação com o responsavel"}]},{"t":"Loja x Infraestrutura","c":[{"t":"Reforça solicitação com o responsavel"}]}],"r6":[{"t":"Passar a visão operacional de loja , cobrar solução de demandas (OS) e receber instruções de novas ações"}]},"nomes_ref":{"vloja":"Visita à loja","vtec":"Visita técnica"}},"rotina_titulo":"Rotina diária na loja — da abertura ao fechamento","rotina_sub":"O que o gerente regional acompanha (e cobra) em toda visita à loja","prog_titulo":"Programação mensal — a semana do gerente regional","conversa_titulo":"Como conduzir a conversa com o gerente de loja"}$j$::jsonb WHERE id = 'regional';
UPDATE areas SET conteudo = conteudo || $j${"rotina_loja":[["S1","Diagnóstico + OTB",["Resultado, margem e cobertura do mês anterior","Leitura de estoque e saldos a liquidar","Definir o orçamento de compra (OTB)","Plano de compra por linha"]],["S2","Negociação + pedidos",["Rodada de negócios e seleção","Negociar condições, VPC e brindes","Fechar e colocar os pedidos"]],["S3","Follow-up + recebimento",["Acompanhar produção e embarque","Recebimento no CD e distribuição","Pedidos emergenciais / de última hora"]],["S4","Abastecimento + próximo ciclo",["Acompanhar venda, ruptura e reposição","Análise parcial e ajustes","Planejar o próximo ciclo (OTB)"]]],"conversa":[["Margem, cobertura & resultado","💰",["Como estão margem, cobertura e fluxo de caixa por linha?","Meta de venda da data x OTB disponível?","Fluxo de caixa e prazo médio de compra (PMP)?"]],["Sortimento & mix","🧺",["A curadoria e os produtos-foco estão definidos para a data?","Itens-presente e faixas de preço (entrada, presente, âncora)?","Grade e profundidade por cluster de loja?"]],["OTB & orçamento","📊",["O orçamento de compra (OTB) está confirmado com a Diretoria?","Qual a margem-alvo da data?","A política de preço está definida?"]],["Negociação & fornecedores","🤝",["O que foi negociado (preço, prazo, troca/consignação)?","Verba cooperada (VPC) e brindes — fechados com quais fornecedores?","Principais fornecedores e seus SLAs de entrega?"]],["Abastecimento & ruptura","📦",["Cobertura adequada por linha? Risco de ruptura?","Datas-limite de recebimento e distribuição (D-45 / D-30 / D-15)?","Plano de reposição durante a campanha?"]],["Integração, dados & time","🔗",["Compras alimenta CRM/Marketing/VM (mix, brindes, VPC) a tempo?","Usam BI e curva ABC para decidir?","Estrutura da equipe e principais gargalos?"]]],"programacao":{"semanas":[{"n":"Semana do comprador(a)","foco":"Rotina diária de Compras","obj":"Rotina semanal do comprador — da revisão da agenda à inclusão de pedidos — ancorada nos indicadores e dashboards do Power BI de Compras.","dias":[{"d":"Segunda-feira","tasks":[{"t":"1 - Revisão da Agenda Diária","c":[{"t":"Objetivo: Revisar a programação semanal de atendimento a fornecedores, visita as lojas, reuniões, viagens e analise de indicadores. Destaque para reunião semanal com as areas do ecossistema de comunicação interna : Marketing, Logística, CRM e Operação de Loja . Analise de indicadores de venda, compras e orçamento."}]},{"t":"2- Analise da Venda","ref":"r1"},{"t":"3 - Analise de estoque","c":[{"t":"Estoque por loja","c":[{"t":"Dashboard Compras: Aba : Estoque Atual Aba : Estoque Atual - (Detalhado)"}]},{"t":"Estoque por nivel de preço","c":[{"t":"Dashboard compras: Aba:Nível de preço (pç)"}]},{"t":"Estoque por idade","c":[{"t":"Dashboard compras: Aba: Estoque por ano"}]},{"t":"Estoque de avarias (defeito)","c":[{"t":"Dashboard compras:"}]}]},{"t":"4 - Pedidos pendente","ref":"r2"},{"t":"5 - Reunião Semanal (Plano de ação para venda)","c":[{"t":"Entrega de vinte produtos para divulgação em rede social e lista de transmissão. (cinco por dia no mínimo)"},{"t":"Apresentar sugestões para ações sobre as linhas, grupo ou marca de baixo desempenho na venda"},{"t":"Apresentar novos produtos se houver"},{"t":"Apresentar ou coletar a pesquisa de mercado e concorrentes local. (Preço, forma de pagamento e exposição de produtos isso não pode faltar nesta pesquisa)"}]},{"t":"6 - Orçamento de Compras (OTB)","ref":"r3"},{"t":"7 - Atendimento de fornecedor / representante","ref":"r4"},{"t":"8 - Solicitação ou inclusão de pedido de compras","ref":"r5"},{"t":"9 - Realizar pedido de transferência para combater a ruptura","ref":"r6"},{"t":"10 - Inclusão, ajuste de pedido de compra"}]},{"d":"Terça-feira","tasks":[{"t":"1 - Revisão da Agenda Diária","ref":"r7"},{"t":"2- Analise da Venda","ref":"r1"},{"t":"3 - Analise de estoque","ref":"r8"},{"t":"4 - Pedidos pendente","ref":"r2"},{"t":"5 - Orçamento de Compras (OTB)","ref":"r3"},{"t":"6 - Visita a loja / Concorrência","ref":"r9"},{"t":"7 - Solicitação ou inclusão de pedido de compras","ref":"r10"},{"t":"8 - Atendimento de fornecedor / representante","ref":"r4"},{"t":"9 - Realizar pedido de transferencia para combater a ruptura","ref":"r11"}]},{"d":"Quarta-feira","tasks":[{"t":"1 - Revisão da Agenda Diária","c":[{"t":"Objetivo: Revisar a programação semanal de atendimento a fornecedores, visita as lojas, reuniões, viagens e analise de indicadores. Destaque para programação de fornecedores agendados para atendimento e revisão do plano de ação de recuperação da venda (combate a concorrência). Analise de indicadores de venda, compras e orçamento."}]},{"t":"2- Analise da Venda","ref":"r1"},{"t":"3 - Analise de estoque","c":[{"t":"Estoque por loja","c":[{"t":"Dashboard Compras: Aba Estoque Atual Aba : Estoque Atual - (Detalhado)"}]},{"t":"Estoque por nivel de preço","c":[{"t":"Dashboard compras: Nivel de preço (pç)"}]},{"t":"Estoque por idade","c":[{"t":"Dashboard compras: Estoque por ano"}]},{"t":"Estoque de avarias (defeito)","c":[{"t":"Dashboard compras: A ser desenvolvido"}]},{"t":"Objetivo: Analisa produtos dos fornecedores que serão atendidos, buscando entender possivel pontos de ruptura e excesso. No caso das rupturar de produtos de alto desempenho devemos realizar a recompra, ja o excesso realizar apontamento para o fornecedor e busca um solução em conjunto com a fabrica para não venda. Em alguns casos a fabrica tem uma tratativa ferente para estes produtos, caso contrario devemos tomar nota para na reunião de planejamento de combate a concorrência utilizar essa informação."}]},{"t":"4 - Pedidos pendente","ref":"r2"},{"t":"5 - Orçamento de Compras (OTB)","ref":"r3"},{"t":"6 - Analise da concorrência","c":[{"t":"1 - Analise dos produtos de encarte semanal ou quinzenal dos concorrêntes. Material envido pelas lojas ou colido na visita semanal as lojas","c":[{"t":"O que analisar ?","c":[{"t":"1 - Temos o mesmo produto a venda nas lojas?"},{"t":"2 - Temos produtos similar a venda nas lojas?"},{"t":"3 - Nivel de preço que estamos praticando esta dentro do nivel que o concorrente esta trabalhando?"},{"t":"4 - Produto esta em area de destaque na loja?"}]}]},{"t":"2 - Analise do material enviado pela area de marketing, referente a pesquisa dos produtos divulgados nas redes social de cada concorrente regional onde possuimos lojas (Minimo de 10 produto por concorrente)","c":[{"t":"Sugestão","c":[{"t":"1 - Criar material e divulgar produto similar ou que complemente o que esta sendo divulgado pelo concorrente."},{"t":"2 - Produtos em destaque nas redes sociais do concorrente e nossas devem esta exposto em loja em area de facil visualização."}]}]}]},{"t":"7 - Criar plano de oportunidade de combate a concorrência semanal","c":[{"t":"Sugestão","c":[{"t":"Reunião com o time de marketing para analise em conjunto o material levantado nas analise da concorrência e criação das ações"},{"t":"Lista de produtos de oportunidade com base na analise realizada pela concorrência e aposta do comprador"},{"t":"Precificação para acompanhar a concorrência. ATENÇÃO : Devemos evitar leilão de produtos iguais, porem podemos ser agressivos em produtos similares"}]}]},{"t":"8 - Atendimento de fornecedor / representante","ref":"r4"},{"t":"7 - Solicitação ou inclusão de pedido de compras","ref":"r10"},{"t":"8 - Realizar pedido de transferencia para combater a ruptura","ref":"r11"},{"t":"9 - Inclusão, ajuste de pedido de compra"},{"t":"10 - Ajuste de preço","ref":"r12"},{"t":"11 - Reunião Emergencial (Recuperação de Venda)","c":[{"t":"Quando necessario"},{"t":"Escopo similar a reunião semanal, porem com foco nas linhas, grupos e marcas com baixa performace"}]}]},{"d":"Quinta-feira","tasks":[{"t":"1 - Revisão da Agenda Diária","ref":"r7"},{"t":"2- Analise da Venda","ref":"r1"},{"t":"3 - Analise de estoque","ref":"r8"},{"t":"4 - Pedidos pendente","ref":"r2"},{"t":"5 - Orçamento de Compras (OTB)","ref":"r3"},{"t":"6 - Visita a loja / Concorrência","ref":"r9"},{"t":"7 - Solicitação ou inclusão de pedido de compras","ref":"r10"},{"t":"8 - Atendimento de fornecedor / representante","ref":"r4"},{"t":"9 - Inclusão, ajuste de pedido de compra"},{"t":"10 - Ajuste de preço","ref":"r12"},{"t":"11 - Realizar pedido de transferencia para combater a ruptura","ref":"r11"},{"t":"12 - Reunião de controle de estoque (Ruptura)","c":[{"t":"Quando necessario"},{"t":"Revisão dos produtos com estoque negativo"},{"t":"Definir data de ajuste e responsavel"},{"t":"Identificar falhas no recebimento"},{"t":"Identificar problemas na operação de etiquetagem, movimentação de estoque"}]}]},{"d":"Sexta-feira","tasks":[{"t":"1 - Revisão da Agenda Diária","c":[{"t":"Objetivo: Revisar a programação semanal de atendimento a fornecedores, visita as lojas, reuniões, viagens e analise de indicadores. Destaque para analise dos indicadores de compra e venda com objetivo de planejar as atividades da próxima semana."}]},{"t":"2- Analise da Venda","ref":"r1"},{"t":"3 - Analise de estoque","ref":"r8"},{"t":"4 - Pedidos pendente","ref":"r2"},{"t":"6 - Planejamento da proxima semana","c":[{"t":"1 - Criar cronograma de visita as lojas 2 - Criar cronograma de atendimento de fornecedores 3 - Revisar e aprovar produtos de combate a concorrência e de aposta de venda (Destaque em loja, Encarte, Carro de son e Rede Social) 4 - Cronograma de viagem feiras, roda de negocio, shopping de rua (SP) e visita a fornecedores"}]},{"t":"7 - Orçamento de Compras (OTB)","c":[{"t":"Por linha","c":[{"t":"Dashboard compras: A ser desenvolvido"}]},{"t":"Reunião com area de planejamento ou financeiro","c":[{"t":"Apresentação do valor realizado em pedido de compra até o final do orçamento","c":[{"t":"Dashboard Financeiro : Acumulado contas a pagar"}]},{"t":"Readequação de valores das verbas"}]}]},{"t":"8 - Atendimento de fornecedor / representante","ref":"r4"},{"t":"9 - Solicitação ou inclusão de pedido de compras","ref":"r5"},{"t":"10 - Realizar pedido de transferencia para combater a ruptura","ref":"r6"},{"t":"11 - Inclusão, ajuste de pedido de compra"}]}]}],"blocos":{"r1":[{"t":"Objetivo : Analisar a venda do mês atual, crescimento em peça, crescimento em valor, margem, markup, ticket médio e fluxo e clientes. Com base nesses indicadores identificar oportunidades de venda, suporte a loja ou plano de ação emergencial."},{"t":"Analise diária (essencial)","c":[{"t":"Venda x Meta lojas","c":[{"t":"Dashboard de compras : 1 - Aba : Venda do Mês x Meta"},{"t":"Objetivo: Analisar o desempenho das vendas comparado com meta estipulada. Resultado esperado: Identificar lojas que requerem uma analise detalhada, com objetivo de criar ações de suporte a loja para melhorar o resultado. Possíveis causas: Area de compras - Mix de produto sem aderência a região ou sazonalidade - Falta de itens de atração ao clientes. trabalhando com produto de coleção antiga ou de preço acima da média. - Falta de produtos para campanhas - Falta produtos de modinha - Etc"}]},{"t":"Venda por loja","c":[{"t":"Dashboard de compras : 2 - Aba : Venda - Resultado Comparativo Analisar a venda do mês atual, crescimento em peça, crescimento em valor, margem, markup, ticket médio e fluxo e clientes, 3 - Aba : Venda Participação Vertical Analisar o crescimento das lojas, linhas, grupos e marcas. Realizando a leitura dos demais indicadores para identificar pontos de oportunidade ou ajuste. 4 - Aba : Venda - Tempo de Vida Analisar o desempenho dos produtos por idade de estoque. É possivel identificar o escoamento desses produtos, por loja, linha, grupo e marca. 5 - Aba : Venda - Diária Analise a venda da semana atual e semana anterior, buscar identificar a sazonalidade diaria da venda. Ação analisar ruptura, precificação, coleção e exposição de produtos. 6 - Aba: Venda - Linha x Grupo Analise da participação das linhas por loja e estoque. 7 - Aba: Nivel de Preço Analise do nivel de preço vendido por linha e loja."}]}]},{"t":"Analise diária (apoio)","c":[{"t":"Venda e estoque por grade","c":[{"t":"Dashboard de compras: Aba: Venda - Grade (Cor e Tamanho) Analise da grade vendida e estoque atual, por Cor, Tamanho, Nivel de preço e Marca"}]},{"t":"Venda por nivel de preço, markup, margem e etc","c":[{"t":"Dashboard de compras: Abas : - Venda - Linha x Marca - Analise por Linha - Crescimento por Lojas - Crescimento po Linha - Venda Promoção - Analítico Promoção - Analise Nivel de Preço2"}]}]}],"r2":[{"t":"Verificar com time se falta digitar pedido","c":[{"t":"Se reunir com o time toda manhã para realizar alinhamento das pendencias e apoio que o time precisa"}]},{"t":"Verificar pedido pendentes por linha e marca","c":[{"t":"Dashboard compra: Pedido de compras"}]},{"t":"Verificar pedido pendente por nivel de preço","c":[{"t":"Dashboard compras: Pedido de compras"}]}],"r3":[{"t":"Por linha","c":[{"t":"Dashboard compras: A ser desenvolvido"}]}],"r4":[{"t":"Book para atendimento a parti do dashboard de compras","c":[{"t":"Dashboard compras: 1 - Aba Estoque Ano 2 - Aba Nivel de preço (2) 3 - Aba Nivel de preço 4 - Aba Grade (Cor e Tamanho) 5 - Aba Venda anual"}]}],"r5":[{"t":"Dashcompra : Aba Pedido de compra"}],"r6":[{"t":"Dashcompra: 1 - Aba Estoque anual 2 - Aba Estoque atual"}],"r7":[{"t":"Objetivo: Revisar a programação semanal de atendimento a fornecedores, visita as lojas, reuniões, viagens e analise de indicadores. Destaque para programação de visita as lojas do grupo e concorrência local. Analise de indicadores de venda e estoque."}],"r8":[{"t":"Estoque por loja","c":[{"t":"Dashboard Compras: Aba Estoque Atual Aba : Estoque Atual - (Detalhado)"}]},{"t":"Estoque por nivel de preço","c":[{"t":"Dashboard compras: Nivel de preço (pç)"}]},{"t":"Estoque por idade","c":[{"t":"Dashboard compras: Estoque por ano"}]},{"t":"Estoque de avarias (defeito)","c":[{"t":"Dashboard compras: A ser desenvolvido"}]}],"r9":[{"t":"1 - Visita a loja Milla","c":[{"t":"Conversa com o gerente sobre o impacto dos concorrentes : 1 - O que eles tem que não temos. 2 - Qual os produtos em destaque no interior da loja 3 - Encarte da semana 4 - Produto no site e rede sociais em destaque. 5 - Nivel de preço praticado 6 - Organização da loja"},{"t":"Conversa com os vendedores de forma pontual, buscando entender como esta a vende e dificuldade"},{"t":"Conversa com o time de logistica (Estoque), buscando entender como esta a operação de recebimento e expedição de transferencias : 1 - Principais dificuldades 2 - Necessidade apoio pontual com algum fornecedor 3 - Qualidade do estoque negativo (volume) 4 - Armazenamento de produtos precificados 5 - Quantidade de produtos no estoque de avarias (defeito)"}]},{"t":"2 - Visita as lojas dos concorrêntes proximos","c":[{"t":"Visita a concorrência : Minimo 2 lojas 1 - O que eles tem que não temos. 2 - Qual os produtos em destaque no interior da loja 3 - Nivel de preço praticado 4 - Organização da loja 5 - Programão de parcelamento 6 - Principais marcas 7 - Principais modelos 8 - Nesta semana a organização da lojas esta voltada para qual publico : Jovem, Infantil, Adulto Feminino, Adulto Masculino 9 - Loja possui area de saldo (Queima) 10 - Qual a campanha a loja esta praticando"}]}],"r10":[{"t":"Objetivo: Eliminar pedidos de gaveta e a falta de digita de qualquer pedido"},{"t":"Dashcompra : Aba Pedido de compra"}],"r11":[{"t":"Dashcompra: 1 - Aba Estoque anual 2 - Aba Estoque atual"},{"t":"Objetivo: O Comprador com base na analise realizada nos paineis de estoque deve real"}],"r12":[{"t":"Alterar preço de venda (Urgente/ajuste)"},{"t":"Agendar de alteração de preço (Programado/ajuste)"}]},"nomes_ref":{"vloja":"Visita à loja","vtec":"Visita técnica"}},"rotina_titulo":"Ritmo do mês — como Compras roda o mês","rotina_sub":"Compra com antecedência (D-45 a D-120); no mês corrente, o S3 cuida dos pedidos emergenciais","prog_titulo":"Programação semanal — a semana do comprador(a)","conversa_titulo":"Como conduzir a conversa com a gestora de Compras"}$j$::jsonb WHERE id = 'compras';
